class Solution {
    public int romanToInt(String s) {
        Map<Character, Integer> d = Map.of('I', 1, 'V', 5, 'X', 10, 'L', 50, 'C', 100, 'D', 500, 'M', 1000);
        int ans = d.get(s.charAt(s.length() - 1));
        for (int i = 0; i + 1 < s.length(); i++) {
            int a = d.get(s.charAt(i)), b = d.get(s.charAt(i + 1));
            ans += a < b ? -a : a;
        }
        return ans;
    }
}

