class Solution {
    public String longestPrefix(String s) {
        int n = s.length();
        int[] lps = new int[n];
        for (int i = 1, k = 0; i < n; i++) {
            while (k > 0 && s.charAt(i) != s.charAt(k)) k = lps[k - 1];
            if (s.charAt(i) == s.charAt(k)) k++;
            lps[i] = k;
        }
        return s.substring(0, lps[n - 1]);
    }
}

