class Solution {
    public List<Integer> majorityElement(int[] nums) {
        int n1 = 0, n2 = 0, m1 = 0, m2 = 1;
        for (int m : nums) {
            if (m == m1) n1++;
            else if (m == m2) n2++;
            else if (n1 == 0) { m1 = m; n1 = 1; }
            else if (n2 == 0) { m2 = m; n2 = 1; }
            else { n1--; n2--; }
        }
        List<Integer> ans = new ArrayList<>();
        for (int m : new int[] {m1, m2}) {
            int c = 0;
            for (int x : nums) if (x == m) c++;
            if (c > nums.length / 3) ans.add(m);
        }
        return ans;
    }
}

