class Solution {
    public int maxSubarraySumCircular(int[] nums) {
        int total = 0, curMax = 0, curMin = 0, best = Integer.MIN_VALUE, worst = Integer.MAX_VALUE;
        for (int x : nums) {
            total += x;
            curMax = Math.max(curMax + x, x);
            best = Math.max(best, curMax);
            curMin = Math.min(curMin + x, x);
