class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String w : words) cnt.merge(w, 1, Integer::sum);
        int m = s.length(), n = words.length, k = words[0].length();
        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            Map<String, Integer> window = new HashMap<>();
            int l = i, r = i;
            while (r + k <= m) {
                String t = s.substring(r, r + k);
                r += k;
                if (!cnt.containsKey(t)) {
                    l = r;
                    window.clear();
                    continue;
                }
                window.merge(t, 1, Integer::sum);
                while (window.get(t) > cnt.get(t)) {
                    window.merge(s.substring(l, l + k), -1, Integer::sum);
                    l += k;
                }
                if (r - l == n * k) ans.add(l);
            }
        }
        return ans;
    }
}

