class Solution {
    public boolean checkInclusion(String s1, String s2) {
        int m = s1.length();
        int[] cnt = new int[128];
        for (char c : s1.toCharArray()) cnt[c]++;
        int need = 0;
        for (int v : cnt) if (v > 0) need++;
        for (int i = 0; i < s2.length(); i++) {
            if (--cnt[s2.charAt(i)] == 0) need--;
            if (i >= m && ++cnt[s2.charAt(i - m)] == 1) need++;
            if (need == 0) return true;
        }
        return false;
    }
}

