class Solution {
    public int reversePairs(long[] nums) {
        return mergeSort(nums, 0, nums.length - 1);
    }

    private int mergeSort(long[] nums, int l, int r) {
        if (l >= r) return 0;
        int mid = (l + r) >>> 1;
        int ans = mergeSort(nums, l, mid) + mergeSort(nums, mid + 1, r);
        for (int i = l, j = mid + 1; i <= mid && j <= r;) {
            if (nums[i] <= 2 * nums[j]) i++;
            else {
                ans += mid - i + 1;
                j++;
            }
        }
        long[] t = new long[r - l + 1];
        int i = l, j = mid + 1, k = 0;
        while (i <= mid && j <= r) t[k++] = nums[i] <= nums[j] ? nums[i++] : nums[j++];
        while (i <= mid) t[k++] = nums[i++];
        while (j <= r) t[k++] = nums[j++];
        System.arraycopy(t, 0, nums, l, t.length);
        return ans;
    }
}

