class Solution {
    public List<Integer> sortArray(int[] nums) {
        quickSort(nums, 0, nums.length - 1);
        return Arrays.stream(nums).boxed().toList();
    }

    private void quickSort(int[] nums, int l, int r) {
        if (l >= r) return;
        int x = nums[l + (int) (Math.random() * (r - l + 1))];
        // Three-way partition: [l..i] < x, (i..k) == x, [j..r] > x.
        int i = l - 1, j = r + 1, k = l;
        while (k < j) {
            if (nums[k] < x) swap(nums, ++i, k++);
            else if (nums[k] > x) swap(nums, --j, k);
            else k++;
        }
        quickSort(nums, l, i);
        quickSort(nums, j, r);
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

