                if (!placed) {
                    ans.add(new int[] {s, e});
                    placed = true;
                }
                ans.add(it);
            } else {
                s = Math.min(s, it[0]);
                e = Math.max(e, it[1]);
            }
        }
        if (!placed) ans.add(new int[] {s, e});
        return ans.stream().map(it -> List.of(it[0], it[1])).toList();
    }
}

