class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        int mx = 0;
        for (int x : bloomDay) mx = Math.max(mx, x);
        int lo = 0, hi = mx + 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (bouquets(bloomDay, k, mid) >= m) hi = mid;
            else lo = mid + 1;
        }
        return lo > mx ? -1 : lo;
    }

    private int bouquets(int[] bloomDay, int k, int day) {
        int cnt = 0, cur = 0;
        for (int x : bloomDay) {
            cur = x <= day ? cur + 1 : 0;
            if (cur == k) {
                cnt++;
                cur = 0;
            }
        }
        return cnt;
    }
}

