class Solution {
    public int divide(long dividend, int divisor) {
        boolean negative = (dividend < 0) != (divisor < 0);
        long a = Math.abs(dividend), b = Math.abs((long) divisor), quotient = 0;
        while (a >= b) {
            long temp = b, multiple = 1;
            while ((temp << 1) <= a) {
                temp <<= 1;
                multiple <<= 1;
            }
            quotient += multiple;
            a -= temp;
