class Solution {
    public String shortestPalindrome(String s) {
        // KMP failure function of s + "#" + reverse(s): the longest
        // palindromic prefix of s.
        String t = s + "#" + new StringBuilder(s).reverse();
        int[] lps = new int[t.length()];
        for (int i = 1, k = 0; i < t.length(); i++) {
            while (k > 0 && t.charAt(i) != t.charAt(k)) k = lps[k - 1];
            if (t.charAt(i) == t.charAt(k)) k++;
            lps[i] = k;
        }
        int idx = lps[t.length() - 1];
        return new StringBuilder(s.substring(idx)).reverse() + s;
    }
}

