class Solution {
    private final Map<Integer, Integer> pos = new HashMap<>();
    private int[] postorder;

    public TreeNode buildTree(int[] inorder, int[] postorder) {
        this.postorder = postorder;
        for (int i = 0; i < inorder.length; i++) pos.put(inorder[i], i);
        return dfs(0, 0, inorder.length);
    }

    // The subtree whose inorder starts at i and postorder at j, n nodes long.
    private TreeNode dfs(int i, int j, int n) {
        if (n <= 0) return null;
        int v = postorder[j + n - 1], k = pos.get(v);
        TreeNode left = dfs(i, j, k - i);
        TreeNode right = dfs(k + 1, j + k - i, n - k + i - 1);
        return new TreeNode(v, left, right);
    }
}

