class Solution {
    private final Map<Integer, Integer> pos = new HashMap<>();
    private int[] preorder;

    public TreeNode constructFromPrePost(int[] preorder, int[] postorder) {
        this.preorder = preorder;
        for (int i = 0; i < postorder.length; i++) pos.put(postorder[i], i);
        return dfs(0, preorder.length - 1, 0);
    }

    // preorder[a..b] is the subtree; its postorder starts at c.
    private TreeNode dfs(int a, int b, int c) {
        if (a > b) return null;
        TreeNode root = new TreeNode(preorder[a]);
        if (a == b) return root;
        int i = pos.get(preorder[a + 1]), m = i - c + 1;
        root.left = dfs(a + 1, a + m, c);
        root.right = dfs(a + m + 1, b, i + 1);
        return root;
