class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        // Positions are renumbered from 0 on every level so they never overflow.
        Deque<Object[]> q = new ArrayDeque<>();
        q.offer(new Object[] {root, 0L});
        long ans = 0;
        while (!q.isEmpty()) {
            long first = (long) q.peekFirst()[1], last = (long) q.peekLast()[1];
            ans = Math.max(ans, last - first + 1);
            for (int k = q.size(); k > 0; k--) {
                Object[] e = q.poll();
                TreeNode node = (TreeNode) e[0];
                long i = (long) e[1] - first;
                if (node.left != null) q.offer(new Object[] {node.left, 2 * i});
                if (node.right != null) q.offer(new Object[] {node.right, 2 * i + 1});
            }
        }
