class Solution {
    private List<Integer>[] g;
    private int[] nums;
    private int total, s1, ans = Integer.MAX_VALUE;

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        this.nums = nums;
        g = new List[n];
        Arrays.setAll(g, k -> new ArrayList<>());
        for (int[] e : edges) {
            g[e[0]].add(e[1]);
            g[e[1]].add(e[0]);
        }
        for (int v : nums) total ^= v;
        // Cut edge (i, j) first; then try every second cut inside i's side.
        for (int i = 0; i < n; i++) {
            for (int j : g[i]) {
                s1 = xor(i, -1, j);
                cutAgain(i, -1, j);
            }
        }
        return ans;
    }

    private int xor(int i, int parent, int banned) {
        int res = nums[i];
        for (int j : g[i]) if (j != parent && j != banned) res ^= xor(j, i, banned);
        return res;
    }

    private int cutAgain(int i, int parent, int banned) {
        int res = nums[i];
        for (int j : g[i]) {
            if (j == parent || j == banned) continue;
            int a = cutAgain(j, i, banned), b = s1 ^ a, c = total ^ s1;
            res ^= a;
            ans = Math.min(ans, Math.max(a, Math.max(b, c)) - Math.min(a, Math.min(b, c)));
        }
        return res;
    }
}

