class Solution {
    public List<Integer> boundaryOfBinaryTree(TreeNode root) {
        List<Integer> ans = new ArrayList<>();
        ans.add(root.val);
        if (isLeaf(root)) return ans;
        for (TreeNode t = root.left; t != null && !isLeaf(t); t = t.left != null ? t.left : t.right) {
            ans.add(t.val);
        }
        leaves(root, ans);
        List<Integer> right = new ArrayList<>();
        for (TreeNode t = root.right; t != null && !isLeaf(t); t = t.right != null ? t.right : t.left) {
            right.add(t.val);
        }
        Collections.reverse(right);
        ans.addAll(right);
        return ans;
    }

    private boolean isLeaf(TreeNode t) {
        return t.left == null && t.right == null;
    }

    private void leaves(TreeNode t, List<Integer> out) {
        if (t == null) return;
        if (isLeaf(t)) {
            out.add(t.val);
            return;
        }
        leaves(t.left, out);
        leaves(t.right, out);
    }
}

