class Solution {
    private int m, n;
    private int[][] heights;
    private static final int[] DIRS = {-1, 0, 1, 0, -1};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        this.heights = heights;
        m = heights.length;
        n = heights[0].length;
        boolean[][] pacific = new boolean[m][n], atlantic = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            dfs(i, 0, pacific);
            dfs(i, n - 1, atlantic);
        }
        for (int j = 0; j < n; j++) {
            dfs(0, j, pacific);
            dfs(m - 1, j, atlantic);
        }
        List<List<Integer>> ans = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (pacific[i][j] && atlantic[i][j]) ans.add(List.of(i, j));
            }
        }
        return ans;
    }

    // Flow backwards: climb from the ocean to every cell that drains into it.
    private void dfs(int i, int j, boolean[][] seen) {
        if (seen[i][j]) return;
        seen[i][j] = true;
        for (int d = 0; d < 4; d++) {
            int x = i + DIRS[d], y = j + DIRS[d + 1];
            if (x >= 0 && x < m && y >= 0 && y < n && heights[x][y] >= heights[i][j]) dfs(x, y, seen);
        }
    }
}

