    public int minDays(int[][] grid) {
        m = grid.length;
        n = grid[0].length;
        if (islands(grid) != 1) return 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    if (islands(grid) != 1) return 1;
                    grid[i][j] = 1;
