        int cnt = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !seen[i][j]) {
                    fill(grid, seen, i, j);
                    cnt++;
                }
            }
        }
        return cnt;
    }

    private void fill(int[][] grid, boolean[][] seen, int i, int j) {
        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0 || seen[i][j]) return;
        seen[i][j] = true;
        fill(grid, seen, i + 1, j);
        fill(grid, seen, i - 1, j);
        fill(grid, seen, i, j + 1);
        fill(grid, seen, i, j - 1);
    }
}

