class Solution {
    private int m, n;
    private int[][] grid;

    public int numDistinctIslands2(int[][] grid) {
        this.grid = grid;
        m = grid.length;
        n = grid[0].length;
        Set<String> shapes = new HashSet<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    List<int[]> cells = new ArrayList<>();
                    dfs(i, j, cells);
                    shapes.add(normalize(cells));
                }
            }
        }
        return shapes.size();
    }

    private void dfs(int i, int j, List<int[]> cells) {
        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) return;
        grid[i][j] = 0;
        cells.add(new int[] {i, j});
        dfs(i + 1, j, cells);
        dfs(i - 1, j, cells);
        dfs(i, j + 1, cells);
        dfs(i, j - 1, cells);
    }

    // The smallest of the 8 rotations/reflections, each shifted to start at 0,0.
    private String normalize(List<int[]> cells) {
        String best = null;
        for (int t = 0; t < 8; t++) {
            List<int[]> pts = new ArrayList<>();
            for (int[] c : cells) {
                int x = c[0], y = c[1];
                int[] p = switch (t) {
                    case 0 -> new int[] {x, y};
                    case 1 -> new int[] {x, -y};
                    case 2 -> new int[] {-x, y};
                    case 3 -> new int[] {-x, -y};
                    case 4 -> new int[] {y, x};
                    case 5 -> new int[] {y, -x};
                    case 6 -> new int[] {-y, x};
                    default -> new int[] {-y, -x};
                };
                pts.add(p);
            }
            pts.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
            StringBuilder sb = new StringBuilder();
            int[] o = pts.get(0);
            for (int[] p : pts) sb.append(p[0] - o[0]).append(',').append(p[1] - o[1]).append(';');
            String key = sb.toString();
            if (best == null || key.compareTo(best) < 0) best = key;
        }
        return best;
    }
}

