class Solution {
    private int n;
    private int[][] grid, id;
    private static final int[] DIRS = {-1, 0, 1, 0, -1};

    public int largestIsland(int[][] grid) {
        this.grid = grid;
        n = grid.length;
        id = new int[n][n];
        List<Integer> size = new ArrayList<>();
        size.add(0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && id[i][j] == 0) size.add(label(i, j, size.size()));
            }
        }
        int ans = Collections.max(size);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) continue;
                Set<Integer> near = new HashSet<>();
                for (int d = 0; d < 4; d++) {
                    int x = i + DIRS[d], y = j + DIRS[d + 1];
                    if (x >= 0 && x < n && y >= 0 && y < n) near.add(id[x][y]);
                }
                int s = 1;
                for (int r : near) s += size.get(r);
                ans = Math.max(ans, s);
            }
        }
        return ans;
    }

    private int label(int i, int j, int root) {
        id[i][j] = root;
        int cnt = 1;
        for (int d = 0; d < 4; d++) {
            int x = i + DIRS[d], y = j + DIRS[d + 1];
            if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1 && id[x][y] == 0) cnt += label(x, y, root);
        }
        return cnt;
    }
}

