class Solution {
    public List<Integer> sortItems(int n, int m, int[] group, int[][] beforeItems) {
        // An item with no group gets a group of its own.
        int idx = m;
        List<Integer>[] groupItems = new List[n + m];
        Arrays.setAll(groupItems, k -> new ArrayList<>());
        for (int i = 0; i < n; i++) {
            if (group[i] == -1) group[i] = idx++;
            groupItems[group[i]].add(i);
        }
        int[] itemDegree = new int[n], groupDegree = new int[n + m];
        List<Integer>[] itemGraph = new List[n], groupGraph = new List[n + m];
        Arrays.setAll(itemGraph, k -> new ArrayList<>());
        Arrays.setAll(groupGraph, k -> new ArrayList<>());
        for (int i = 0; i < n; i++) {
            for (int j : beforeItems[i]) {
                if (group[i] == group[j]) {
                    itemDegree[i]++;
                    itemGraph[j].add(i);
                } else {
                    groupDegree[group[i]]++;
                    groupGraph[group[j]].add(group[i]);
                }
            }
        }
        List<Integer> allGroups = new ArrayList<>();
        for (int g = 0; g < n + m; g++) allGroups.add(g);
        List<Integer> groupOrder = topoSort(groupDegree, groupGraph, allGroups);
        if (groupOrder.isEmpty()) return List.of();
        List<Integer> ans = new ArrayList<>();
        for (int g : groupOrder) {
            List<Integer> order = topoSort(itemDegree, itemGraph, groupItems[g]);
            if (order.size() != groupItems[g].size()) return List.of();
            ans.addAll(order);
        }
        return ans;
    }

    private List<Integer> topoSort(int[] degree, List<Integer>[] graph, List<Integer> items) {
        Deque<Integer> q = new ArrayDeque<>();
        for (int i : items) if (degree[i] == 0) q.offer(i);
        List<Integer> res = new ArrayList<>();
        while (!q.isEmpty()) {
            int i = q.poll();
            res.add(i);
            for (int j : graph[i]) if (--degree[j] == 0) q.offer(j);
        }
        return res.size() == items.size() ? res : new ArrayList<>();
    }
}

