class Solution {
    public List<List<Integer>> buildMatrix(int k, int[][] rowConditions, int[][] colConditions) {
        int[] row = order(k, rowConditions), col = order(k, colConditions);
        if (row == null || col == null) return List.of();
        int[] colOf = new int[k + 1];
        for (int i = 0; i < k; i++) colOf[col[i]] = i;
        int[][] ans = new int[k][k];
        for (int i = 0; i < k; i++) ans[i][colOf[row[i]]] = row[i];
        return Arrays.stream(ans).map(r -> Arrays.stream(r).boxed().toList()).toList();
    }

    // A topological order of 1..k, or null when the conditions form a cycle.
    private int[] order(int k, int[][] cond) {
        List<Integer>[] g = new List[k + 1];
        Arrays.setAll(g, x -> new ArrayList<>());
        int[] indeg = new int[k + 1];
        for (int[] c : cond) {
            g[c[0]].add(c[1]);
            indeg[c[1]]++;
        }
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= k; i++) if (indeg[i] == 0) q.offer(i);
        int[] res = new int[k];
        int t = 0;
        while (!q.isEmpty()) {
            int i = q.poll();
            res[t++] = i;
            for (int j : g[i]) if (--indeg[j] == 0) q.offer(j);
        }
        return t == k ? res : null;
    }
}

