class Solution {
    public String alienOrder(String[] words) {
        boolean[][] g = new boolean[26][26];
        boolean[] seen = new boolean[26];
        int cnt = 0;
        for (String w : words) {
            for (char c : w.toCharArray()) {
                if (!seen[c - 'a']) {
                    seen[c - 'a'] = true;
                    cnt++;
                }
            }
        }
        // Each adjacent pair gives at most one edge: its first differing letter.
        for (int i = 0; i + 1 < words.length; i++) {
            String a = words[i], b = words[i + 1];
            int j = 0;
            while (j < a.length() && j < b.length() && a.charAt(j) == b.charAt(j)) j++;
            if (j == a.length()) continue;
            if (j == b.length()) return "";
            int o1 = a.charAt(j) - 'a', o2 = b.charAt(j) - 'a';
            if (g[o2][o1]) return "";
            g[o1][o2] = true;
        }
        int[] indeg = new int[26];
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < 26; j++) if (i != j && g[i][j]) indeg[j]++;
        }
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < 26; i++) if (seen[i] && indeg[i] == 0) q.offer(i);
        StringBuilder ans = new StringBuilder();
        while (!q.isEmpty()) {
            int t = q.poll();
            ans.append((char) ('a' + t));
            for (int i = 0; i < 26; i++) {
                if (i != t && g[t][i] && --indeg[i] == 0) q.offer(i);
            }
        }
        return ans.length() < cnt ? "" : ans.toString();
    }
}

