class Solution {
    private final Map<String, String> p = new HashMap<>();
    private final Map<String, Double> w = new HashMap<>();

    public List<Double> calcEquation(String[][] equations, double[] values, String[][] queries) {
        for (String[] e : equations) {
            for (String v : e) {
                p.put(v, v);
                w.put(v, 1.0);
            }
        }
        // w[x] = x / root(x)
        for (int i = 0; i < values.length; i++) {
            String a = equations[i][0], b = equations[i][1];
            String pa = find(a), pb = find(b);
            if (pa.equals(pb)) continue;
            p.put(pa, pb);
            w.put(pa, w.get(b) * values[i] / w.get(a));
        }
        double[] ans = new double[queries.length];
        for (int i = 0; i < ans.length; i++) {
            String c = queries[i][0], d = queries[i][1];
            ans[i] = !p.containsKey(c) || !p.containsKey(d) || !find(c).equals(find(d))
                ? -1
                : w.get(c) / w.get(d);
        }
        return Arrays.stream(ans).boxed().toList();
    }

    private String find(String x) {
        String parent = p.get(x);
        if (!parent.equals(x)) {
            String root = find(parent);
            w.put(x, w.get(x) * w.get(parent));
            p.put(x, root);
        }
        return p.get(x);
    }
}

