class Solution {
    private int[] p;

    public int swimInWater(int[][] grid) {
        int n = grid.length;
        p = new int[n * n];
        for (int i = 0; i < n * n; i++) p[i] = i;
        // at[h] = the cell whose height is h
        int[] at = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) at[grid[i][j]] = i * n + j;
        }
        int[] dirs = {-1, 0, 1, 0, -1};
        // Raise the water one level at a time, joining each newly covered
        // cell to its covered neighbours, until corner meets corner.
        for (int t = 0; t < n * n; t++) {
            int i = at[t] / n, j = at[t] % n;
            for (int d = 0; d < 4; d++) {
                int x = i + dirs[d], y = j + dirs[d + 1];
                if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] <= t) {
                    p[find(x * n + y)] = find(at[t]);
                }
                if (find(0) == find(n * n - 1)) return t;
            }
        }
        return -1;
    }

    private int find(int x) {
        return p[x] == x ? x : (p[x] = find(p[x]));
    }
