class Solution {
    public List<Integer> getOrder(int[][] tasks) {
        int n = tasks.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, Comparator.comparingInt((Integer i) -> tasks[i][0]).thenComparingInt(i -> tasks[i][1]).thenComparingInt(i -> i));
        // Ready tasks: shortest processing time first, then lowest index.
        PriorityQueue<int[]> q = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : a[1] - b[1]);
        int[] ans = new int[n];
        long t = 0;
        for (int i = 0, k = 0; k < n;) {
            if (q.isEmpty()) t = Math.max(t, tasks[idx[i]][0]);
            while (i < n && tasks[idx[i]][0] <= t) {
                q.offer(new int[] {tasks[idx[i]][1], idx[i]});
                i++;
            }
            int[] e = q.poll();
            ans[k++] = e[1];
            t += e[0];
        }
        return Arrays.stream(ans).boxed().toList();
    }
}

