class Solution {
    public List<Double> medianSlidingWindow(int[] nums, int k) {
        // Sorted multiset of the window as (value, index) pairs.
        Comparator<Integer> cmp = (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : a - b;
        TreeSet<Integer> low = new TreeSet<>(cmp), high = new TreeSet<>(cmp);
        double[] ans = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            low.add(i);
            high.add(low.pollLast());
            if (high.size() > low.size()) low.add(high.pollFirst());
            if (i >= k - 1) {
                int start = i - k + 1;
                ans[start] = k % 2 == 1 ? nums[low.last()] : ((double) nums[low.last()] + nums[high.first()]) / 2;
                if (!low.remove(start)) high.remove(start);
                if (low.size() < high.size()) low.add(high.pollFirst());
                else if (low.size() > high.size() + 1) high.add(low.pollLast());
            }
        }
        return Arrays.stream(ans).boxed().toList();
    }
}

