class Solution {
    public int findTheCity(int n, int[][] edges, int distanceThreshold) {
        final int INF = 1 << 29;
        int[][] d = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(d[i], INF);
            d[i][i] = 0;
        }
        for (int[] e : edges) d[e[0]][e[1]] = d[e[1]][e[0]] = e[2];
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) d[i][j] = Math.min(d[i][j], d[i][k] + d[k][j]);
            }
        }
        // Fewest reachable cities; ties go to the largest index.
        int ans = -1, best = Integer.MAX_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            int cnt = 0;
            for (int j = 0; j < n; j++) if (d[i][j] <= distanceThreshold) cnt++;
            if (cnt < best) {
                best = cnt;
                ans = i;
            }
        }
        return ans;
    }
}

