class Solution {
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        final int INF = 0x3f3f3f3f;
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        // Round r allows r flights; copying keeps each round to one more hop.
        for (int r = 0; r <= k; r++) {
            int[] backup = dist.clone();
            for (int[] f : flights) dist[f[1]] = Math.min(dist[f[1]], backup[f[0]] + f[2]);
