class Solution {
    public int reachableNodes(int[][] edges, int maxMoves, int n) {
        List<int[]>[] g = new List[n];
        Arrays.setAll(g, k -> new ArrayList<>());
        for (int[] e : edges) {
            g[e[0]].add(new int[] {e[1], e[2] + 1});
            g[e[1]].add(new int[] {e[0], e[2] + 1});
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(e -> e[0]));
        pq.offer(new int[] {0, 0});
        while (!pq.isEmpty()) {
            int[] e = pq.poll();
            if (e[0] > dist[e[1]]) continue;
            for (int[] edge : g[e[1]]) {
                int t = e[0] + edge[1];
                if (t < dist[edge[0]]) {
                    dist[edge[0]] = t;
                    pq.offer(new int[] {t, edge[0]});
                }
            }
        }
        int ans = 0;
        for (int d : dist) if (d <= maxMoves) ans++;
        // New nodes on each edge: reached from both ends, never more than cnt.
        for (int[] e : edges) {
            int a = dist[e[0]] == Integer.MAX_VALUE ? 0 : Math.min(e[2], Math.max(0, maxMoves - dist[e[0]]));
            int b = dist[e[1]] == Integer.MAX_VALUE ? 0 : Math.min(e[2], Math.max(0, maxMoves - dist[e[1]]));
            ans += Math.min(e[2], a + b);
        }
        return ans;
    }
}

