class Solution {
    private int[] p;
    private int parts;

    public List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {
        int m = edges.length;
        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> edges[i][2]));
        int best = mst(n, edges, order, -1, -1);
        List<Integer> critical = new ArrayList<>(), pseudo = new ArrayList<>();
        for (int i : order) {
            // Without it the MST gets heavier (or falls apart): critical.
            int without = mst(n, edges, order, i, -1);
            if (without == -1 || without > best) critical.add(i);
            // Forced in, it still makes a minimum tree: pseudo-critical.
            else if (mst(n, edges, order, -1, i) == best) pseudo.add(i);
        }
        return List.of(critical, pseudo);
    }

    // MST weight skipping edge `skip` and starting with edge `force`; -1 if disconnected.
    private int mst(int n, int[][] edges, Integer[] order, int skip, int force) {
        p = new int[n];
        for (int i = 0; i < n; i++) p[i] = i;
        parts = n;
        int w = 0;
        if (force >= 0) {
            union(edges[force][0], edges[force][1]);
            w += edges[force][2];
        }
        for (int i : order) {
            if (i != skip && union(edges[i][0], edges[i][1])) w += edges[i][2];
        }
        return parts == 1 ? w : -1;
    }

    private boolean union(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        p[a] = b;
        parts--;
        return true;
    }

    private int find(int x) {
        return p[x] == x ? x : (p[x] = find(p[x]));
    }
}

