class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length >> 1;
        // f[c] / g[c]: signed sums of the left / right half with c numbers
        // on the positive side.
        List<Set<Integer>> f = new ArrayList<>(), g = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            f.add(new HashSet<>());
            g.add(new HashSet<>());
        }
        for (int mask = 0; mask < 1 << n; mask++) {
            int s = 0, s1 = 0, cnt = Integer.bitCount(mask);
            for (int j = 0; j < n; j++) {
                boolean in = (mask >> j & 1) == 1;
                s += in ? nums[j] : -nums[j];
                s1 += in ? nums[n + j] : -nums[n + j];
            }
            f.get(cnt).add(s);
            g.get(cnt).add(s1);
        }
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i <= n; i++) {
            TreeSet<Integer> gi = new TreeSet<>(g.get(n - i));
            for (int a : f.get(i)) {
                Integer hi = gi.ceiling(-a), lo = gi.floor(-a);
                if (hi != null) ans = Math.min(ans, Math.abs(a + hi));
                if (lo != null) ans = Math.min(ans, Math.abs(a + lo));
            }
        }
        return ans;
    }
}

