    private int[] nums;
    private final List<List<Integer>> ans = new ArrayList<>();
    private final List<Integer> t = new ArrayList<>();

    public List<List<Integer>> findSubsequences(int[] nums) {
        this.nums = nums;
        dfs(0, Integer.MIN_VALUE);
        return ans;
    }

    // Take nums[u] if it keeps the run non-decreasing; skip it only when it
    // differs from `last`, so equal values are never chosen twice the same way.
    private void dfs(int u, int last) {
        if (u == nums.length) {
            if (t.size() > 1) ans.add(new ArrayList<>(t));
            return;
        }
        if (nums[u] >= last) {
            t.add(nums[u]);
            dfs(u + 1, nums[u]);
            t.remove(t.size() - 1);
        }
        if (nums[u] != last) dfs(u + 1, last);
    }
}

