class Solution {
    private int[] sticks, edges = new int[4];
    private int side;

    public boolean makesquare(int[] matchsticks) {
        int sum = 0, mx = 0;
        for (int x : matchsticks) {
            sum += x;
            mx = Math.max(mx, x);
        }
        side = sum / 4;
        if (sum % 4 != 0 || mx > side) return false;
        // Longest first: dead ends show up sooner.
        sticks = Arrays.stream(matchsticks).boxed().sorted(Collections.reverseOrder()).mapToInt(Integer::intValue).toArray();
        return dfs(0);
    }

    private boolean dfs(int u) {
        if (u == sticks.length) return true;
        for (int i = 0; i < 4; i++) {
            if (i > 0 && edges[i - 1] == edges[i]) continue;
            edges[i] += sticks[u];
            if (edges[i] <= side && dfs(u + 1)) return true;
            edges[i] -= sticks[u];
        }
        return false;
    }
