        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] == '#') return;
        char c = board[i][j];
        node = node.children[c - 'a'];
        if (node == null) return;
        if (node.ref >= 0) {
            ans.add(words[node.ref]);
            node.ref = -1;
        }
        board[i][j] = '#';
        dfs(node, i - 1, j);
        dfs(node, i, j + 1);
        dfs(node, i + 1, j);
        dfs(node, i, j - 1);
        board[i][j] = c;
