class Solution {
    public int findMaximumXOR(long[] nums) {
        // Build the answer bit by bit: can some pair reach `ans | bit`?
        int ans = 0, mask = 0;
        for (int i = 30; i >= 0; i--) {
            mask |= 1 << i;
            Set<Integer> prefixes = new HashSet<>();
            for (long x : nums) prefixes.add((int) x & mask);
            int want = ans | 1 << i;
            for (int p : prefixes) {
