class Solution {
    private final Set<String> dict = new HashSet<>();

    public List<String> findAllConcatenatedWordsInADict(String[] words) {
        String[] sorted = words.clone();
        Arrays.sort(sorted, Comparator.comparingInt(String::length));
        List<String> ans = new ArrayList<>();
        // Shorter words first: a word can only be built from shorter ones.
        for (String w : sorted) {
            if (!w.isEmpty() && canBuild(w, 0)) ans.add(w);
            else dict.add(w);
        }
        return ans;
    }

    private boolean canBuild(String w, int start) {
        if (start == w.length()) return true;
        for (int end = start + 1; end <= w.length(); end++) {
            if (dict.contains(w.substring(start, end)) && canBuild(w, end)) return true;
        }
        return false;
