class Solution {
    public List<String> wordsAbbreviation(String[] words) {
        // Words clash only with others of the same length and last letter;
        // count, per group, how many share each prefix.
        Map<String, Integer> prefixCount = new HashMap<>();
        for (String w : words) {
            String group = w.length() + "" + w.charAt(w.length() - 1) + ":";
            for (int i = 1; i <= w.length(); i++) prefixCount.merge(group + w.substring(0, i), 1, Integer::sum);
        }
        List<String> ans = new ArrayList<>();
        for (String w : words) {
            String group = w.length() + "" + w.charAt(w.length() - 1) + ":";
            int cnt = w.length();
            for (int i = 1; i <= w.length(); i++) {
                if (prefixCount.get(group + w.substring(0, i)) == 1) {
                    cnt = i;
                    break;
                }
            }
            ans.add(cnt + 2 >= w.length() ? w : w.substring(0, cnt) + (w.length() - cnt - 1) + w.charAt(w.length() - 1));
        }
        return ans;
    }
}

