class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length, i = n - 1, j = n - 1, cnt = 0, s = 0;
        // Drive forward from j; whenever the tank goes negative, move the
        // start i one station back to pick up its surplus.
        while (cnt < n) {
            s += gas[j] - cost[j];
            cnt++;
            j = (j + 1) % n;
            while (s < 0 && cnt < n) {
                i--;
                s += gas[i] - cost[i];
                cnt++;
            }
        }
        return s < 0 ? -1 : i;
    }
}

