class Solution {
    public String longestDiverseString(int a, int b, int c) {
        // {count, letter}: most left first, ties by letter.
        PriorityQueue<int[]> h = new PriorityQueue<>((x, y) -> x[0] != y[0] ? y[0] - x[0] : x[1] - y[1]);
        if (a > 0) h.offer(new int[] {a, 'a'});
        if (b > 0) h.offer(new int[] {b, 'b'});
        if (c > 0) h.offer(new int[] {c, 'c'});
        StringBuilder ans = new StringBuilder();
        while (!h.isEmpty()) {
            int[] cur = h.poll();
            int n = ans.length();
            if (n >= 2 && ans.charAt(n - 1) == cur[1] && ans.charAt(n - 2) == cur[1]) {
                if (h.isEmpty()) break;
                int[] next = h.poll();
                ans.append((char) next[1]);
                if (--next[0] > 0) h.offer(next);
                h.offer(cur);
            } else {
                ans.append((char) cur[1]);
                if (--cur[0] > 0) h.offer(cur);
            }
        }
        return ans.toString();
    }
}

