class Solution {
    public List<String> maxNumOfSubstrings(String s) {
        int[] left = new int[26], right = new int[26];
        Arrays.fill(left, -1);
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (left[c] == -1) left[c] = i;
            right[c] = i;
        }
        // Grow each letter's span until it holds every occurrence of every
        // letter inside it.
        List<int[]> segs = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            if (left[i] == -1) continue;
            int l = left[i], r = right[i];
            for (int j = l; j <= r; j++) {
                int c = s.charAt(j) - 'a';
                if (left[c] < l || right[c] > r) {
                    l = Math.min(l, left[c]);
                    r = Math.max(r, right[c]);
                    j = l;
                }
            }
            segs.add(new int[] {l, r});
        }
        // Greedy: earliest end first (on a tie, the shorter one).
        segs.sort((x, y) -> x[1] != y[1] ? x[1] - y[1] : y[0] - x[0]);
        List<String> ans = new ArrayList<>();
        int end = -1;
        for (int[] seg : segs) {
            if (seg[0] > end) {
                end = seg[1];
                ans.add(s.substring(seg[0], seg[1] + 1));
            }
        }
        return ans;
    }
}

