class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);
        PriorityQueue<Integer> idle = new PriorityQueue<>();
        for (int i = 0; i < n; i++) idle.offer(i);
        // {free at, room}
        PriorityQueue<long[]> busy = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        int[] cnt = new int[n];
        for (int[] m : meetings) {
            long s = m[0], e = m[1];
            while (!busy.isEmpty() && busy.peek()[0] <= s) idle.offer((int) busy.poll()[1]);
            if (!idle.isEmpty()) {
                int i = idle.poll();
                cnt[i]++;
                busy.offer(new long[] {e, i});
            } else {
                long[] b = busy.poll();
                cnt[(int) b[1]]++;
                busy.offer(new long[] {b[0] + e - s, b[1]});
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++) if (cnt[i] > cnt[ans]) ans = i;
        return ans;
    }
}

