class Solution {
    public String predictPartyVictory(String senate) {
        int n = senate.length();
        Deque<Integer> qr = new ArrayDeque<>(), qd = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') qr.offer(i);
            else qd.offer(i);
        }
        // The earlier senator bans the other and votes again next round.
        while (!qr.isEmpty() && !qd.isEmpty()) {
            int r = qr.poll(), d = qd.poll();
            if (r < d) qr.offer(r + n);
