    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        // Binary-search the left end of the best window of k.
        int lo = 0, hi = arr.length - k;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (x - arr[mid] > arr[mid + k] - x) lo = mid + 1;
            else hi = mid;
