class Solution {
    public String reorganizeString(String s) {
        int n = s.length();
        Map<Character, Integer> cnt = new LinkedHashMap<>();
        for (char c : s.toCharArray()) cnt.merge(c, 1, Integer::sum);
        if (Collections.max(cnt.values()) > (n + 1) / 2) return "";
        List<Character> letters = new ArrayList<>(cnt.keySet());
        letters.sort((a, b) -> cnt.get(b) - cnt.get(a));
        // Fill even slots first, most common letter first, then odd ones.
        char[] ans = new char[n];
        int i = 0;
        for (char c : letters) {
            for (int v = cnt.get(c); v > 0; v--) {
                ans[i] = c;
                i += 2;
                if (i >= n) i = 1;
            }
        }
        return new String(ans);
    }
}

