class Solution {
    public int minCut(String s) {
        int n = s.length();
        boolean[][] pal = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                pal[i][j] = s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1]);
            }
        }
        int[] f = new int[n];
        for (int i = 0; i < n; i++) {
            f[i] = i;
            for (int j = 0; j <= i; j++) {
                if (pal[j][i]) f[i] = Math.min(f[i], j == 0 ? 0 : f[j - 1] + 1);
            }
        }
        return f[n - 1];
    }
