    public boolean canReach(String s, int minJump, int maxJump) {
        int n = s.length();
        boolean[] f = new boolean[n];
        f[0] = true;
        // pre[i] = how many reachable indices in [0, i)
        int[] pre = new int[n + 1];
        pre[1] = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == '0') {
                int l = Math.max(0, i - maxJump), r = i - minJump;
                f[i] = l <= r && pre[r + 1] - pre[l] > 0;
