class Solution {
    public List<Integer> largestDivisibleSubset(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length, k = 0;
        int[] f = new int[n];
        for (int i = 0; i < n; i++) {
            f[i] = 1;
            for (int j = 0; j < i; j++) {
                if (nums[i] % nums[j] == 0) f[i] = Math.max(f[i], f[j] + 1);
            }
            if (f[k] < f[i]) k = i;
        }
        // Walk back from the end of the longest chain.
        List<Integer> ans = new ArrayList<>();
        for (int m = f[k], i = k; m > 0; i--) {
            if (nums[k] % nums[i] == 0 && f[i] == m) {
                ans.add(nums[i]);
                k = i;
                m--;
            }
        }
        return ans;
    }
}

