class Solution {
    public int lastStoneWeightII(int[] stones) {
        int s = Arrays.stream(stones).sum(), half = s / 2;
        // Largest pile weight <= half that some subset can make.
        boolean[] can = new boolean[half + 1];
        can[0] = true;
        for (int x : stones) {
            for (int j = half; j >= x; j--) can[j] |= can[j - x];
