class Solution {
    public List<Integer> pathsWithMaxScore(String[] board) {
        final int mod = 1_000_000_007;
        int n = board.length;
        // f = best score from (i, j) to the bottom-right, g = number of ways.
        int[][] f = new int[n + 1][n + 1];
        long[][] g = new long[n + 1][n + 1];
        for (int[] row : f) Arrays.fill(row, -1);
        f[n - 1][n - 1] = 0;
        g[n - 1][n - 1] = 1;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                char c = board[i].charAt(j);
                if (c == 'X' || c == 'S') continue;
                for (int[] d : new int[][] {{1, 0}, {0, 1}, {1, 1}}) {
                    int x = i + d[0], y = j + d[1];
                    if (f[x][y] == -1) continue;
                    if (f[x][y] > f[i][j]) {
                        f[i][j] = f[x][y];
                        g[i][j] = g[x][y];
                    } else if (f[x][y] == f[i][j]) {
                        g[i][j] = (g[i][j] + g[x][y]) % mod;
                    }
                }
                if (f[i][j] != -1 && Character.isDigit(c)) f[i][j] += c - '0';
            }
        }
        return f[0][0] == -1 ? List.of(0, 0) : List.of(f[0][0], (int) (g[0][0] % mod));
    }
}

