class Solution {
    public String shortestCommonSupersequence(String str1, String str2) {
        int m = str1.length(), n = str2.length();
        int[][] f = new int[m + 1][n + 1];
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                f[i][j] = str1.charAt(i - 1) == str2.charAt(j - 1)
                    ? f[i - 1][j - 1] + 1
                    : Math.max(f[i - 1][j], f[i][j - 1]);
            }
        }
        // Walk the LCS table back, emitting every letter once.
        StringBuilder ans = new StringBuilder();
        int i = m, j = n;
        while (i > 0 || j > 0) {
            if (i == 0) ans.append(str2.charAt(--j));
            else if (j == 0) ans.append(str1.charAt(--i));
            else if (f[i][j] == f[i - 1][j]) ans.append(str1.charAt(--i));
            else if (f[i][j] == f[i][j - 1]) ans.append(str2.charAt(--j));
            else {
                j--;
                ans.append(str1.charAt(--i));
            }
        }
        return ans.reverse().toString();
    }
}

