class Solution {
    private String s1, s2;
    private final Map<String, Boolean> memo = new HashMap<>();

    public boolean possiblyEquals(String s1, String s2) {
        this.s1 = s1;
        this.s2 = s2;
        return dp(0, 0, 0);
    }

    // Every length a run of digits can stand for ("12" -> 12 or 1 + 2).
    private Set<Integer> nums(String s) {
        Set<Integer> out = new HashSet<>();
        out.add(Integer.parseInt(s));
        for (int i = 1; i < s.length(); i++) {
            for (int x : nums(s.substring(0, i))) {
                for (int y : nums(s.substring(i))) out.add(x + y);
            }
        }
        return out;
    }

    private int nextLetter(String s, int i) {
        while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
        return i;
    }

    // diff > 0: s1 has that many more wildcard characters pending than s2.
    private boolean dp(int i, int j, int diff) {
        if (i == s1.length() && j == s2.length()) return diff == 0;
        String key = i + "," + j + "," + diff;
        Boolean hit = memo.get(key);
        if (hit != null) return hit;
        boolean ans = false;
        if (i < s1.length() && Character.isDigit(s1.charAt(i))) {
            int next = nextLetter(s1, i);
            for (int num : nums(s1.substring(i, next))) {
                if (dp(next, j, diff + num)) {
                    ans = true;
                    break;
                }
            }
        } else if (j < s2.length() && Character.isDigit(s2.charAt(j))) {
            int next = nextLetter(s2, j);
            for (int num : nums(s2.substring(j, next))) {
                if (dp(i, next, diff - num)) {
                    ans = true;
                    break;
                }
            }
        } else if (diff > 0) {
            ans = j < s2.length() && dp(i, j + 1, diff - 1);
        } else if (diff < 0) {
            ans = i < s1.length() && dp(i + 1, j, diff + 1);
        } else {
            ans = i < s1.length() && j < s2.length() && s1.charAt(i) == s2.charAt(j) && dp(i + 1, j + 1, 0);
        }
        memo.put(key, ans);
        return ans;
    }
}

