        // contains s2[..j) as a subsequence; 0 if none.
        int[][] f = new int[m + 1][n + 1];
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) f[i][j] = j == 1 ? i : f[i - 1][j - 1];
