class Solution {
    public int kIncreasing(int[] arr, int k) {
        int ans = 0;
        for (int start = 0; start < k; start++) {
            // Longest non-decreasing subsequence of arr[start], arr[start+k], ...
            List<Integer> tails = new ArrayList<>();
            int len = 0;
            for (int i = start; i < arr.length; i += k) {
                len++;
                int x = arr[i], lo = 0, hi = tails.size();
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (tails.get(mid) <= x) lo = mid + 1;
                    else hi = mid;
                }
                if (lo == tails.size()) tails.add(x);
                else tails.set(lo, x);
            }
            ans += len - tails.size();
        }
        return ans;
    }
}

