class Solution {
    private int[] s;
    private int[][] memo;

    public int stoneGameV(int[] stoneValue) {
        int n = stoneValue.length;
        s = new int[n + 1];
        for (int i = 0; i < n; i++) s[i + 1] = s[i] + stoneValue[i];
        memo = new int[n][n];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(0, n - 1);
    }

    private int dfs(int i, int j) {
        if (i >= j) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        int ans = 0;
        for (int k = i; k < j; k++) {
            int l = s[k + 1] - s[i], r = s[j + 1] - s[k + 1];
            // Bob throws away the larger row; Alice keeps the smaller one.
            if (l < r) {
                if (ans >= 2 * l) continue;
                ans = Math.max(ans, l + dfs(i, k));
            } else if (l > r) {
                if (ans >= 2 * r) break;
                ans = Math.max(ans, r + dfs(k + 1, j));
            } else {
                ans = Math.max(ans, Math.max(l + dfs(i, k), r + dfs(k + 1, j)));
            }
        }
        return memo[i][j] = ans;
    }
}

