class Solution {
    public int scoreOfStudents(String s, int[] answers) {
        int n = s.length(), m = (n + 1) / 2;
        // The correct value: multiplication first.
        int correct = 0, pre = s.charAt(0) - '0';
        for (int i = 1; i < n; i += 2) {
            int d = s.charAt(i + 1) - '0';
            if (s.charAt(i) == '*') pre *= d;
            else {
                correct += pre;
                pre = d;
            }
        }
        correct += pre;
        // f[i][j] = every value (<= 1000) digits i..j can reach in some order.
        Set<Integer>[][] f = new Set[m][m];
        for (int i = m - 1; i >= 0; i--) {
            for (int j = i; j < m; j++) {
                f[i][j] = new HashSet<>();
                if (i == j) {
                    f[i][j].add(s.charAt(2 * i) - '0');
                    continue;
                }
                for (int k = i; k < j; k++) {
                    char op = s.charAt(2 * k + 1);
                    for (int l : f[i][k]) {
                        for (int r : f[k + 1][j]) {
                            int v = op == '+' ? l + r : l * r;
                            if (v <= 1000) f[i][j].add(v);
                        }
                    }
                }
            }
        }
        int ans = 0;
        for (int a : answers) {
            if (a == correct) ans += 5;
            else if (f[0][m - 1].contains(a)) ans += 2;
        }
        return ans;
    }
}

