class Solution {
    public String encode(String s) {
        int n = s.length();
        String[][] f = new String[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                String t = s.substring(i, j + 1);
                f[i][j] = t;
                if (t.length() < 5) continue;
                // t repeats with period k iff t is found inside t + t before k = |t|.
                int k = (t + t).indexOf(t, 1);
                if (k < t.length()) f[i][j] = t.length() / k + "[" + f[i][i + k - 1] + "]";
                for (int m = i; m < j; m++) {
                    String split = f[i][m] + f[m + 1][j];
                    if (split.length() < f[i][j].length()) f[i][j] = split;
                }
            }
        }
        return f[0][n - 1];
    }
}

