        int lo = 0, hi = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                lo++;
                hi++;
            } else if (c == ')') {
                lo = Math.max(0, lo - 1);
                if (--hi < 0) return false;
            } else {
