class DetectSquares {
    private final Map<Long, Integer> points = new HashMap<>();

    private static long key(int x, int y) {
        return (long) x << 32 | (y & 0xffffffffL);
    }

    public DetectSquares() {}

    public void add(int[] point) {
        points.merge(key(point[0], point[1]), 1, Integer::sum);
    }

    public int count(int[] point) {
        int x = point[0], y = point[1], total = 0;
        // Each stored point is a candidate diagonal corner.
        for (var e : points.entrySet()) {
            int px = (int) (e.getKey() >> 32), py = (int) (long) e.getKey();
            if (px == x || Math.abs(px - x) != Math.abs(py - y)) continue;
            total += e.getValue()
                * points.getOrDefault(key(x, py), 0)
                * points.getOrDefault(key(px, y), 0);
        }
        return total;
    }
}

