class LFUCache {
    private final int capacity;
    private final Map<Integer, Integer> values = new HashMap<>(), freq = new HashMap<>();
    // frequency -> keys in least-recently-used order
    private final Map<Integer, LinkedHashSet<Integer>> groups = new HashMap<>();
    private int minFreq = 0;

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    private void touch(int key) {
        int f = freq.get(key);
        groups.get(f).remove(key);
        if (f == minFreq && groups.get(f).isEmpty()) minFreq++;
        freq.put(key, f + 1);
        groups.computeIfAbsent(f + 1, k -> new LinkedHashSet<>()).add(key);
    }

    public int get(int key) {
        if (!values.containsKey(key)) return -1;
        touch(key);
        return values.get(key);
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        if (values.containsKey(key)) {
            values.put(key, value);
            touch(key);
            return;
        }
        if (values.size() == capacity) {
            Iterator<Integer> it = groups.get(minFreq).iterator();
            int evicted = it.next();
            it.remove();
            values.remove(evicted);
            freq.remove(evicted);
        }
        values.put(key, value);
        freq.put(key, 1);
        groups.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
        minFreq = 1;
    }
}

