class Solution {
    public List<Integer> mergeSort(int[] arr) {
        sort(arr, 0, arr.length);
        return Arrays.stream(arr).boxed().toList();
    }

    private void sort(int[] arr, int left, int right) {
        if (right - left <= 1) return;
        int mid = (left + right) >>> 1;
        sort(arr, left, mid);
        sort(arr, mid, right);
        int[] merged = new int[right - left];
        int i = left, j = mid, k = 0;
        while (i < mid && j < right) merged[k++] = arr[i] <= arr[j] ? arr[i++] : arr[j++];
        while (i < mid) merged[k++] = arr[i++];
        while (j < right) merged[k++] = arr[j++];
        System.arraycopy(merged, 0, arr, left, merged.length);
    }
}

