class Solution {
    public List<Integer> quickSort(int[] arr, int low, int high) {
        sort(arr, low, high);
        return Arrays.stream(arr).boxed().toList();
    }

    private void sort(int[] arr, int low, int high) {
        if (low >= high) return;
        int pivot = arr[(low + high) >>> 1], i = low, j = high;
        while (i <= j) {
            while (arr[i] < pivot) i++;
            while (arr[j] > pivot) j--;
            if (i <= j) {
                int t = arr[i];
                arr[i++] = arr[j];
                arr[j--] = t;
            }
        }
        sort(arr, low, j);
        sort(arr, i, high);
    }
}

