class Solution {
    // long where the starter says int: the answer can outgrow int; the checker accepts either.
    public long inversionCount(int[] arr) {
        return sortCount(arr.clone(), 0, arr.length);
    }

    private long sortCount(int[] a, int left, int right) {
        if (right - left <= 1) return 0;
        int mid = (left + right) >>> 1;
        long count = sortCount(a, left, mid) + sortCount(a, mid, right);
        int[] merged = new int[right - left];
        int i = left, j = mid, k = 0;
        while (i < mid && j < right) {
            if (a[i] <= a[j]) merged[k++] = a[i++];
            else {
                // a[j] jumps ahead of every element still left in the left half.
                count += mid - i;
                merged[k++] = a[j++];
            }
        }
        while (i < mid) merged[k++] = a[i++];
        while (j < right) merged[k++] = a[j++];
        System.arraycopy(merged, 0, a, left, merged.length);
        return count;
    }
}

