class Solution {
    public int aggressiveCows(int[] stalls, int k) {
        int[] pos = stalls.clone();
        Arrays.sort(pos);
        // Largest gap d such that k cows fit at least d apart.
        int lo = 0, hi = pos[pos.length - 1] - pos[0], answer = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (canPlace(pos, k, mid)) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return answer;
    }

    private boolean canPlace(int[] pos, int k, int distance) {
        int count = 1, last = pos[0];
        for (int i = 1; i < pos.length; i++) {
            if (pos[i] - last >= distance) {
                count++;
                last = pos[i];
            }
        }
        return count >= k;
    }
}

