class Solution {
    public int kthElement(int[] a, int[] b, int k) {
        if (a.length > b.length) return kthElement(b, a, k);
        int n = a.length, m = b.length;
        // Binary-search how many of the first k come from a.
        int lo = Math.max(0, k - m), hi = Math.min(k, n);
        while (lo <= hi) {
            int cutA = (lo + hi) >>> 1, cutB = k - cutA;
            long leftA = cutA > 0 ? a[cutA - 1] : Long.MIN_VALUE;
            long rightA = cutA < n ? a[cutA] : Long.MAX_VALUE;
            long leftB = cutB > 0 ? b[cutB - 1] : Long.MIN_VALUE;
            long rightB = cutB < m ? b[cutB] : Long.MAX_VALUE;
            if (leftA <= rightB && leftB <= rightA) return (int) Math.max(leftA, leftB);
            if (leftA > rightB) hi = cutA - 1;
            else lo = cutA + 1;
        }
        return -1;
    }
}

