class Solution {
    public int median(int[][] mat) {
        int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
        for (int[] row : mat) {
            lo = Math.min(lo, row[0]);
            hi = Math.max(hi, row[row.length - 1]);
        }
        int required = mat.length * mat[0].length / 2;
        // Smallest value with more than half the matrix <= it.
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2, count = 0;
            for (int[] row : mat) count += upperBound(row, mid);
            if (count <= required) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

