class Solution {
    public List<Integer> findTwoElement(int[] arr) {
        long n = arr.length, sum = 0, squares = 0;
        for (int v : arr) {
            sum += v;
            squares += (long) v * v;
        }
        // repeating - missing and repeating^2 - missing^2
        long diff = sum - n * (n + 1) / 2;
        long squareDiff = squares - n * (n + 1) * (2 * n + 1) / 6;
