class Solution {
    public List<Integer> topView(TreeNode root) {
        if (root == null) return new ArrayList<>();
        // BFS: the first node seen in each column is the one on top.
        TreeMap<Integer, Integer> first = new TreeMap<>();
        Deque<Object[]> q = new ArrayDeque<>();
        q.offer(new Object[] {root, 0});
        while (!q.isEmpty()) {
            Object[] e = q.poll();
            TreeNode node = (TreeNode) e[0];
            int col = (int) e[1];
            first.putIfAbsent(col, node.val);
            if (node.left != null) q.offer(new Object[] {node.left, col - 1});
            if (node.right != null) q.offer(new Object[] {node.right, col + 1});
        }
        return new ArrayList<>(first.values());
    }
}

