class Solution {
    public List<Integer> distanceK(TreeNode root, int target, int k) {
        List<Integer> out = new ArrayList<>();
        if (root == null) return out;
        // Record parents, so the tree can be walked like an undirected graph.
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        TreeNode start = null;
        Deque<TreeNode> q = new ArrayDeque<>();
        q.offer(root);
        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (node.val == target) start = node;
            for (TreeNode child : new TreeNode[] {node.left, node.right}) {
                if (child != null) {
                    parent.put(child, node);
                    q.offer(child);
                }
            }
        }
        if (start == null) return out;
        Set<TreeNode> seen = new HashSet<>();
        seen.add(start);
        q.offer(start);
        for (int d = 0; d < k && !q.isEmpty(); d++) {
            for (int size = q.size(); size > 0; size--) {
                TreeNode node = q.poll();
                for (TreeNode next : new TreeNode[] {node.left, node.right, parent.get(node)}) {
                    if (next != null && seen.add(next)) q.offer(next);
                }
            }
        }
        for (TreeNode node : q) out.add(node.val);
        return out;
    }
}

