class Solution {
    public int numProvinces(int[][] adj, int V) {
        boolean[] seen = new boolean[V];
        int provinces = 0;
        for (int start = 0; start < V; start++) {
            if (seen[start]) continue;
            provinces++;
            seen[start] = true;
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(start);
            while (!stack.isEmpty()) {
                int node = stack.pop();
                for (int next = 0; next < V; next++) {
                    if (adj[node][next] != 0 && !seen[next]) {
                        seen[next] = true;
                        stack.push(next);
                    }
                }
            }
        }
        return provinces;
    }
}

