        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1) return;
        grid[i][j] = 2;
        shape.append(i - i0).append(',').append(j - j0).append(';');
        dfs(i + 1, j, i0, j0, shape);
        dfs(i - 1, j, i0, j0, shape);
        dfs(i, j + 1, i0, j0, shape);
        dfs(i, j - 1, i0, j0, shape);
    }
}

