class Solution {
    public List<Integer> shortestPath(int N, int M, int[][] edges) {
        List<int[]>[] g = new List[N];
        Arrays.setAll(g, k -> new ArrayList<>());
        int[] indeg = new int[N];
        for (int[] e : edges) {
            g[e[0]].add(new int[] {e[1], e[2]});
            indeg[e[1]]++;
        }
        // Relax edges in topological order: each node is final when reached.
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < N; i++) if (indeg[i] == 0) q.offer(i);
        long[] dist = new long[N];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] e : g[u]) {
                if (dist[u] != Long.MAX_VALUE) dist[e[0]] = Math.min(dist[e[0]], dist[u] + e[1]);
                if (--indeg[e[0]] == 0) q.offer(e[0]);
            }
        }
        int[] ans = new int[N];
        for (int i = 0; i < N; i++) ans[i] = dist[i] == Long.MAX_VALUE ? -1 : (int) dist[i];
        return Arrays.stream(ans).boxed().toList();
    }
}

