class Solution {
    public List<Integer> buildHeap(int[] nums) {
        int[] heap = nums.clone();
        int n = heap.length;
        for (int start = n / 2 - 1; start >= 0; start--) {
            // Sift down into a max-heap.
            for (int i = start;;) {
                int largest = i, left = 2 * i + 1, right = left + 1;
                if (left < n && heap[left] > heap[largest]) largest = left;
                if (right < n && heap[right] > heap[largest]) largest = right;
                if (largest == i) break;
                int t = heap[i];
                heap[i] = heap[largest];
                heap[largest] = t;
                i = largest;
            }
        }
        return Arrays.stream(heap).boxed().toList();
    }
}

