class minHeap {
    private final List<Integer> heap = new ArrayList<>();

    public minHeap() {}

    public void push(int x) {
        heap.add(x);
        for (int i = heap.size() - 1; i > 0;) {
            int parent = (i - 1) / 2;
            if (heap.get(parent) <= heap.get(i)) break;
            Collections.swap(heap, parent, i);
            i = parent;
        }
    }

    public void pop() {
        if (heap.isEmpty()) return;
        int last = heap.remove(heap.size() - 1);
        if (heap.isEmpty()) return;
        heap.set(0, last);
        int n = heap.size();
        for (int i = 0;;) {
            int smallest = i, left = 2 * i + 1, right = left + 1;
            if (left < n && heap.get(left) < heap.get(smallest)) smallest = left;
            if (right < n && heap.get(right) < heap.get(smallest)) smallest = right;
            if (smallest == i) break;
            Collections.swap(heap, i, smallest);
            i = smallest;
        }
    }

    public int peek() {
        return heap.isEmpty() ? -1 : heap.get(0);
    }

    public int size() {
        return heap.size();
    }
}

