class Solution {
    public List<Integer> heapSort(int[] arr) {
        int n = arr.length;
        for (int i = n / 2 - 1; i >= 0; i--) siftDown(arr, i, n);
        // Move the max to the end, shrink the heap, repeat.
        for (int end = n - 1; end > 0; end--) {
            int t = arr[0];
            arr[0] = arr[end];
            arr[end] = t;
            siftDown(arr, 0, end);
        }
        return Arrays.stream(arr).boxed().toList();
    }

    private void siftDown(int[] arr, int root, int end) {
        while (true) {
            int child = 2 * root + 1;
            if (child >= end) return;
            if (child + 1 < end && arr[child + 1] > arr[child]) child++;
            if (arr[root] >= arr[child]) return;
            int t = arr[root];
            arr[root] = arr[child];
            arr[child] = t;
            root = child;
        }
    }
}

