class Solution {
    private int n;
    private int[][] maze;
    private boolean[][] visited;
    private final List<String> answer = new ArrayList<>();
    private static final char[] LETTER = {'D', 'L', 'R', 'U'};
    private static final int[] DR = {1, 0, 0, -1}, DC = {0, -1, 1, 0};

    public List<String> ratInMaze(int[][] maze) {
        n = maze.length;
        if (n == 0 || maze[0][0] == 0 || maze[n - 1][n - 1] == 0) return answer;
        this.maze = maze;
        visited = new boolean[n][n];
        search(0, 0, new StringBuilder());
        return answer;
    }

    // Moves tried in D, L, R, U order, so paths come out sorted.
    private void search(int r, int c, StringBuilder path) {
        if (r == n - 1 && c == n - 1) {
            answer.add(path.toString());
            return;
        }
        visited[r][c] = true;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d], nc = c + DC[d];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && maze[nr][nc] == 1 && !visited[nr][nc]) {
                path.append(LETTER[d]);
                search(nr, nc, path);
                path.deleteCharAt(path.length() - 1);
            }
        }
        visited[r][c] = false;
    }
}

