class Solution {
    private List<Integer>[] adj;
    private int[] colors;
    private int m;

    public boolean graphColoring(int v, int[][] edges, int m) {
        if (v == 0) return true;
        if (m <= 0) return false;
        this.m = m;
        adj = new List[v];
        Arrays.setAll(adj, k -> new ArrayList<>());
        for (int[] e : edges) {
            if (e[0] == e[1]) return false;
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        colors = new int[v];
        Arrays.fill(colors, -1);
        return color(0);
    }

    private boolean color(int node) {
        if (node == colors.length) return true;
        for (int c = 0; c < m; c++) {
            boolean free = true;
            for (int nb : adj[node]) {
                if (colors[nb] == c) {
                    free = false;
                    break;
                }
            }
            if (!free) continue;
            colors[node] = c;
            if (color(node + 1)) return true;
            colors[node] = -1;
        }
        return false;
    }
}

