class WordDictionary {
    private static class Node {
        Node[] children = new Node[26];
        boolean end;
    }

    private final Node root = new Node();

    public WordDictionary() {}

    public void addWord(String word) {
        Node node = root;
        for (char c : word.toCharArray()) {
            if (node.children[c - 'a'] == null) node.children[c - 'a'] = new Node();
            node = node.children[c - 'a'];
        }
        node.end = true;
    }

    public boolean search(String word) {
        return matches(word, 0, root);
    }

    // '.' matches any one letter: try every child.
    private boolean matches(String word, int i, Node node) {
        if (i == word.length()) return node.end;
        char c = word.charAt(i);
        if (c == '.') {
            for (Node child : node.children) {
                if (child != null && matches(word, i + 1, child)) return true;
            }
            return false;
        }
        Node child = node.children[c - 'a'];
        return child != null && matches(word, i + 1, child);
    }
}

