class Solution {
    public int solve(int[] bt) {
        if (bt.length == 0) return 0;
        int[] order = bt.clone();
        Arrays.sort(order);
        // Shortest job first: each job waits for all the shorter ones.
        long elapsed = 0, waiting = 0;
        for (int burst : order) {
            waiting += elapsed;
            elapsed += burst;
        }
        return (int) (waiting / bt.length);
    }
}

