class Solution {
    private int[] parent;

    public List<Integer> jobSequencing(int[] deadline, int[] profit) {
        int n = deadline.length;
        if (n == 0) return List.of(0, 0);
        int maxSlot = Math.min(Arrays.stream(deadline).max().getAsInt(), n);
        parent = new int[maxSlot + 1];
        for (int i = 0; i <= maxSlot; i++) parent[i] = i;
        Integer[] jobs = new Integer[n];
        for (int i = 0; i < n; i++) jobs[i] = i;
        Arrays.sort(jobs, (a, b) -> profit[b] - profit[a]);
        // Most profitable first, into the latest free slot before its deadline.
        int count = 0, total = 0;
        for (int j : jobs) {
            int slot = find(Math.min(deadline[j], maxSlot));
            if (slot > 0) {
                count++;
                total += profit[j];
                parent[slot] = find(slot - 1);
            }
        }
        return List.of(count, total);
    }

    private int find(int x) {
        return parent[x] == x ? x : (parent[x] = find(parent[x]));
    }
}

