class Solution {
    public int maximumMeetings(int[] start, int[] end) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        // Earliest finish first leaves the most room for the rest.
        Arrays.sort(idx, (a, b) -> end[a] != end[b] ? end[a] - end[b] : start[a] - start[b]);
        int count = 0;
        long lastEnd = Long.MIN_VALUE;
        for (int i : idx) {
            if (start[i] > lastEnd) {
                count++;
                lastEnd = end[i];
            }
        }
        return count;
    }
}

