class Solution {
    public int findPlatform(int[] arrival, int[] departure) {
        int n = arrival.length;
        int[] arr = arrival.clone(), dep = departure.clone();
        Arrays.sort(arr);
        Arrays.sort(dep);
        int i = 0, j = 0, inUse = 0, answer = 0;
        while (i < n && j < n) {
            if (arr[i] <= dep[j]) {
                answer = Math.max(answer, ++inUse);
                i++;
            } else {
                inUse--;
                j++;
            }
        }
        return answer;
    }
}

