class Solution {
    public int countSubsequenceWithTargetSum(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        counts.put(0, 1);
        for (int v : nums) {
            Map<Integer, Integer> updated = new HashMap<>(counts);
            for (var e : counts.entrySet()) updated.merge(e.getKey() + v, e.getValue(), Integer::sum);
            counts = updated;
        }
        int answer = counts.getOrDefault(k, 0);
        // The empty subsequence sums to 0 but doesn't count.
        return k == 0 ? answer - 1 : answer;
    }
}
